fn server_config(root: &Path, tool_kind: &str, mode: &str) -> ServerConfig {
    let mut agent = AgentConfig::default();
    let mut env = vec![
        "SEA_ACP_FIXTURE=1".into(),
        format!("FIXTURE_TOOL_KIND={tool_kind}"),
        format!("FIXTURE_MODE={mode}"),
    ];
    if mode.starts_with("swe_seed") {
        let repo = std::env::current_dir().unwrap();
        let commit = std::process::Command::new("git")
            .args(["rev-parse", "HEAD"])
            .current_dir(&repo)
            .output()
            .unwrap();
        assert!(commit.status.success());
        env.push(format!("SEA_FORGE_SWE_SEED_REPO={}", repo.display()));
        let commit = if mode == "swe_seed_bad_commit" {
            "0000000000000000000000000000000000000000".into()
        } else {
            String::from_utf8_lossy(&commit.stdout).trim().to_string()
        };
        env.push(format!("SEA_FORGE_SWE_SEED_COMMIT={commit}"));
    }
    agent.endpoints.push(AgentEndpointConfig {
        id: ENDPOINT.into(),
        kind: ProviderKind::Acp,
        base_url: None,
        argv: vec![
            std::env::current_exe()
                .unwrap()
                .to_string_lossy()
                .into_owned(),
            "--exact".into(),
            "acp_fixture_child".into(),
            "--nocapture".into(),
            "--test-threads=1".into(),
        ],
        env,
        credential_ref: None,
        default_model: Some("fixture".into()),
        allow_loopback_test: false,
        max_request_bytes: 16_384,
        max_response_bytes: 16_384,
        timeout_secs: 3,
        status: None,
        transcript_retention: None,
    });
    ServerConfig {
        root: root.to_path_buf(),
        agent,
        ..ServerConfig::default()
    }
}

async fn execute_fixture(config: &ServerConfig, case: &str) -> (String, DelegationResult) {
    let run = run_id().unwrap();
    let result = delegation::execute_with_control(
        config,
        DelegationRequest {
            endpoint_id: ENDPOINT,
            instruction: "portable ACP task",
            model: None,
            max_turns: 8,
            token_budget: None,
            criteria: SettlementCriteria::default(),
            policy_path: "policy.yaml",
            entity: "operator_local",
            process: "conformance_m16",
            // These M16 tests assert on the plaintext transcript artifact's
            // exact bytes (hash verification, redaction scrubbing) — a full
            // mode concern, orthogonal to the M13 T16 retention-precedence
            // tests in conformance_m13.rs.
            transcript_retention: sea_forge_agent::TranscriptRetentionMode::Full,
            ..Default::default()
        },
        &EnvironmentCredentialResolver,
        DelegationEpisodeContext::planned(case, "item_acp", &run),
    let root = tempfile::tempdir().unwrap();
    write_policy(root.path(), true);
    let case = case_id().unwrap();
    let disconnected = server_config(root.path(), "read", "disconnect");
    let (run, result) = execute_fixture(&disconnected, &case).await;
    assert_eq!(result.settlement, SettlementStatus::Rejected);
    assert_eq!(result.termination.as_deref(), Some("acp_disconnect"));
    assert_eq!(
        result.continuation_key.as_deref(),
        Some("sess-portable-m16")
    );
    let records = entries(root.path(), &case);
    let session = records
        .iter()
        .find(|e| e.record_kind == "acp_session")
        .unwrap();
    assert_eq!(session.payload["continuation_key"], "sess-portable-m16");
    let evidence = records
        .iter()
        .find(|e| e.record_kind == "agent_task_evidence")
        .unwrap();
    let artifact = evidence.payload["artifact_ref"].as_str().unwrap();
    assert!(std::fs::read_to_string(root.path().join(artifact))
        .unwrap()
        .contains("partial"));
    assert!(root
        .path()
        .join("runs")
        .join(run)
        .join("settlement.json")
        .exists());

    let resumed = server_config(root.path(), "read", "normal");
    let (_, resumed_result) = execute_fixture(&resumed, &case).await;
    assert_eq!(resumed_result.settlement, SettlementStatus::Accepted);
    assert_eq!(
        resumed_result.continuation_key, result.continuation_key,
        "successor episode must load and ledger the same ACP session"
    );
    let records = entries(root.path(), &case);
    let linked_sessions: Vec<_> = records
        .iter()
        .filter(|entry| entry.record_kind == "acp_session")
        .collect();
    assert_eq!(linked_sessions.len(), 2);
    assert!(linked_sessions
        .iter()
        .all(|entry| entry.payload["continuation_key"] == "sess-portable-m16"));
}

#[tokio::test]
async fn t16_6_portable_swe_seed_artifacts_are_hashed_and_run_correlated() {
    let (root, case, run, result) = run_fixture("read", "swe_seed", true).await;
    assert_eq!(result.settlement, SettlementStatus::Accepted);
    let records = entries(root.path(), &case);
    let evidence = records
        .iter()
        .find(|entry| entry.record_kind == "agent_task_evidence")
        .unwrap();
    let refs = evidence.payload["harvested_refs"].as_array().unwrap();
    assert_eq!(refs.len(), 2);
    assert!(refs.iter().all(|value| {
        let value = value.as_str().unwrap();
        value.starts_with(&format!("{run}:.agent-harness/")) && value.contains(":sha256:")
    }));
    let correlation = records
        .iter()
        .find(|entry| entry.record_kind == "swe_seed_correlation")
        .unwrap();
    assert_eq!(correlation.payload["run_id"], run);
    assert_eq!(correlation.payload["harvested_refs"], json!(refs));
}

/// Latest matching record for `kind`/`run` — several kinds (notably
/// `swe_seed_correlation`) are append-only and re-committed as their
/// underlying state changes, so callers that want current truth must not
/// take the first match.
fn find_run_field<'a>(
    records: &'a [sea_forge_ledger::LedgerEntry],
    kind: &str,
    run: &str,
) -> &'a Value {
    &records
        .iter()
        .rev()
        .find(|entry| entry.record_kind == kind && entry.payload["run_id"] == run)
        .unwrap_or_else(|| panic!("no {kind} record for run {run}"))
        .payload
}

/// Build a `SettlementDeclaration` that binds exactly to one run's harvested
/// SWE_SEED evidence — the claim manifest hash must be recomputed identically
/// to what `swe_seed_reconciliation` expects, or reconciliation must (by
/// design) refuse to correlate it.
fn matching_swe_seed_declaration(
    case: &str,
    run: &str,
    records: &[sea_forge_ledger::LedgerEntry],
) -> SettlementDeclaration {
    let evidence = find_run_field(records, "agent_task_evidence", run);
    let settlement = find_run_field(records, "settlement", run);
    let harvested_refs: Vec<String> = evidence["harvested_refs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let claim_manifest_sha256 = swe_seed_reconciliation::swe_seed_claim_manifest_sha256(
        case,
        run,
        "item_acp",
        settlement["settlement_id"].as_str().unwrap(),
        evidence["transcript_sha256"].as_str().unwrap(),
        &harvested_refs,
    )
    .unwrap();
    let mut decl = SettlementDeclaration {
        version: "0.2".into(),
        declaration_id: random_id("sdec").unwrap(),
        settlement_ref: settlement["settlement_id"].as_str().unwrap().into(),
        run_id: run.into(),
        case_id: case.into(),
        plan_item_id: "item_acp".into(),
        claim_manifest_sha256,
        status: DeclarationStatus::Accepted,
        strength: SettlementStrength::Strong,
        qualifies_for_capability: true,
        criteria_ref: "crit_out_of_band".into(),
        criteria_sha256: "sha256:crit".into(),
        criteria_record_hash: "sha256:crit-record".into(),
        criteria_declared_at: Utc::now().to_rfc3339(),
        job_contract_ref: None,
        origin_refs: vec![],
        verifier_ref: "swe_seed_harness".into(),
        verifier_sha256: "sha256:verifier".into(),
        verification_evidence_refs: vec![],
        declarer: Declarer {
            actor_id: "swe_seed_verifier".into(),
            authority_ref: "swe_seed_test".into(),
            role: "R-AA".into(),
            standing_basis: "test-attested-verifier".into(),
        },
        independence: DeclarationIndependence {
            acting_entity_id: "operator_local".into(),
            independent: true,
            basis: "swe_seed_independent_verification".into(),
        },
        reliability: DeclarationReliability {
            feedback_delay_ms: 0,
            attribution_confidence: "1.000000".into(),
            gaming_exposure: "0.000000".into(),
            hidden_debt_blindness: "0.000000".into(),
            weight: "1.000000".into(),
            basis: "test".into(),
        },
        variation_tags: Default::default(),
        disruption_tags: vec![],
        orchestration_burden: None,
        issued_at: Utc::now().to_rfc3339(),
        source_evidence_refs: harvested_refs,
        adapter_attestation_ref: None,
        authored_by: None,
        declaration_hash: String::new(),
    };
    decl.declaration_hash = sea_forge_settlement::compute_declaration_hash(&decl).unwrap();
    decl
}

